#include <stdlib.h>

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int m = 2 * (N - 1);
    int *head = malloc((N + 1) * sizeof(int));
    int *to = malloc(m * sizeof(int));
    int *nxt = malloc(m * sizeof(int));

    for (int i = 1; i <= N; i++) head[i] = -1;

    int idx = 0;
    for (int i = 0; i < N - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);

        to[idx] = b;
        nxt[idx] = head[a];
        head[a] = idx++;

        to[idx] = a;
        nxt[idx] = head[b];
        head[b] = idx++;
    }

    int *parent = calloc(N + 1, sizeof(int));
    int *order = malloc(N * sizeof(int));
    int *stack = malloc(N * sizeof(int));

    int top = 0, cnt = 0;
    stack[top++] = 1;
    parent[1] = -1;

    while (top > 0) {
        int v = stack[--top];
        order[cnt++] = v;

        for (int e = head[v]; e != -1; e = nxt[e]) {
            int u = to[e];
            if (u == parent[v]) continue;
            parent[u] = v;
            stack[top++] = u;
        }
    }

    int *sz = malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) sz[i] = 1;

    for (int i = N - 1; i >= 0; i--) {
        int v = order[i];
        if (parent[v] > 0) {
            sz[parent[v]] += sz[v];
        }
    }

    int ans = N;
    for (int v = 2; v <= N; v++) {
        int s = sz[v];
        int diff = N - 2 * s;
        if (diff < 0) diff = -diff;
        if (diff < ans) ans = diff;
    }

    printf("%d\n", ans);

    free(head);
    free(to);
    free(nxt);
    free(parent);
    free(order);
    free(stack);
    free(sz);

    return 0;
}
